cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const { documentId, title, timestamp, idempotencyKey } = input;
const vendorStatus = input.vendorStatus ?? 200;
const json = { "content-type": "application/json" };

function emit(o) {
  console.log(JSON.stringify({
    http: o.http,
    database: o.database ?? { rows: [], transaction: { committed: false, rolledBack: o.rolledBack ?? false } },
    messages: o.messages ?? [],
    outbound: o.outbound ?? [],
    ordering: o.ordering ?? [],
    failures: o.failures ?? [],
    retryability: o.retryability ?? false
  }));
}

function reply(status, body, extra = {}) {
  return { http: { status, headers: json, body }, ...extra };
}

if (typeof title !== "string" || title.trim() === "") {
  emit(reply(400, { error: "invalid_request", field: "title" }, {
    failures: [{ type: "validation", field: "title", status: 400 }]
  }));
} else {
  const document = { id: documentId, title, createdAt: timestamp };
  const prior = input.existing ?? input.replay;

  if (prior && (prior.idempotencyKey ?? idempotencyKey) === idempotencyKey && prior.document) {
    // Idempotent replay: return the stored result, no side effects.
    const same = prior.document.title === title;
    if (!same) {
      emit(reply(422, { error: "idempotency_key_reuse" }, {
        failures: [{ type: "idempotency_conflict", status: 422 }]
      }));
    } else {
      const d = prior.document;
      emit(reply(200, { id: d.id, title: d.title, createdAt: d.createdAt }, {
        headers: json,
        database: { rows: [d], transaction: { committed: false, replayed: true } },
        ordering: ["replay"]
      }));
    }
  } else {
    const outbound = [];
    const ordering = [];
    const call = (name, status) => {
      outbound.push({ vendor: name, documentId, timestamp, idempotencyKey, status });
      ordering.push(`vendor.${name}`);
      return status;
    };
    const stages = ["authorize", "index"];
    let failed = null;
    for (const stage of stages) {
      const status = call(stage, vendorStatus);
      if (status < 200 || status >= 300) { failed = { stage, status }; break; }
    }

    if (failed) {
      const { stage, status } = failed;
      const retryable = status === 408 || status === 429 || status >= 500;
      const out = status === 401 || status === 403 ? 502 : retryable ? (status === 408 ? 504 : 503) : 502;
      emit(reply(out, { error: "vendor_failure", stage }, {
        outbound, ordering,
        rolledBack: false,
        failures: [{ type: "vendor", stage, vendorStatus: status, status: out }],
        retryability: retryable
      }));
    } else {
      ordering.push("db.commit", "event.document.created");
      emit(reply(201, { id: documentId, title, createdAt: timestamp }, {
        database: { rows: [document], transaction: { committed: true } },
        messages: [{ type: "document.created", documentId, timestamp, idempotencyKey, payload: document }],
        outbound, ordering
      }));
    }
  }
}
EOF
